<style>
/* Hide About Me, Blog, Resume from navbar on landing page (they're in the feature cards) */
.navbar-nav .nav-item:not(.compact) {
  display: none;
}

/* Dynamic Page Styles */
.dynamic-page {
  min-height: 100vh;
  position: relative;
  overflow: hidden;
}

/* Animated Gradient Background */
.gradient-bg {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(-45deg, #0f0f23, #1a1a3e, #0d2137, #1a0a2e);
  background-size: 400% 400%;
  animation: gradientShift 15s ease infinite;
  z-index: -2;
}

@keyframes gradientShift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Light mode gradient */
body:not(.quarto-dark) .gradient-bg {
  background: linear-gradient(-45deg, #eef2f6, #e3e8ef, #dbe4ef, #e5eaf2);
  background-size: 400% 400%;
}

/* Hero Section V2 */
.hero-section-v2 {
  position: relative;
  min-height: 50vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 2rem 6rem;
  margin: 5rem 2rem 2rem 2rem;
  border-radius: 24px;
  overflow: hidden;
  background-image: url('images/wide_maroc.jpg');
  background-size: cover;
  background-position: center;
  background-color: #2a2a2a;
}

.hero-section-v2::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: linear-gradient(to right, transparent 0%, rgba(0,0,0,0.6) 100%);
  z-index: 0;
}

.hero-content-v2 {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 3rem;
  margin-left: 15%;
}

.hero-title-v2 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 3rem;
  font-weight: 300;
  line-height: 1.1;
  color: #fff;
  text-shadow: 0 4px 10px rgba(0,0,0,0.3);
  margin: 0;
  white-space: nowrap;
}

.hero-divider {
  width: 1px;
  height: 100px;
  background: rgba(255,255,255,0.5);
}

.hero-subtitle-v2 {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.hero-subtitle-v2 span {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.8rem;
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(255,255,255,0.9);
}

/* Cards Container */
.cards-container {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1.5rem;
  padding: 0 2rem 4rem 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

@media (max-width: 1200px) {
  .cards-container {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .cards-container {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.5rem;
    padding: 0 0.75rem 1rem 0.75rem;
  }

  .feature-card-v2 {
    padding: 0.6rem 0.75rem;
  }

  .card-icon {
    width: 28px;
    height: 28px;
    margin-bottom: 0.4rem;
    border-radius: 8px;
  }

  .card-icon svg {
    width: 14px;
    height: 14px;
  }

  .feature-card-v2 h3 {
    font-size: 0.85rem;
    margin-bottom: 0;
  }

  .feature-card-v2 p {
    max-height: 100px;
    opacity: 0.8;
    font-size: 0.7rem;
    margin-top: 0.2rem;
    overflow: hidden;
  }

  .feature-card-v2 p + p {
    display: none;
  }

  .card-arrow {
    display: none;
  }

  .hero-section-v2 {
    min-height: 200px;
    padding: 1rem;
    margin: 60px 0.75rem 0.75rem 0.75rem;
    border-radius: 16px;
  }

  .hero-title-v2 {
    font-size: 1.5rem;
  }

  .hero-content-v2 {
    flex-direction: column;
    text-align: center;
    margin-left: 0;
    padding-right: 0;
    gap: 1rem;
  }

  .hero-divider {
    width: 60px;
    height: 1px;
    background: rgba(255,255,255,0.5);
  }

  .hero-subtitle-v2 {
    gap: 0.3rem;
  }

  .hero-subtitle-v2 span {
    font-size: 0.65rem;
  }
}

/* Feature Card V2 */
.feature-card-v2 {
  position: relative;
  padding: 1.25rem 1.5rem;
  background: rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(20px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 16px;
  text-decoration: none;
  color: #fff;
  transition: all 0.5s cubic-bezier(0.23, 1, 0.32, 1);
  overflow: hidden;
  cursor: pointer;
}

.feature-card-v2::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, rgba(255,255,255,0.1) 0%, transparent 50%);
  opacity: 0;
  transition: opacity 0.5s ease;
  pointer-events: none;
}

.feature-card-v2:hover {
  transform: translateY(-10px) scale(1.02);
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.3);
  box-shadow:
    0 25px 50px -12px rgba(0, 0, 0, 0.4),
    0 0 40px rgba(255, 255, 255, 0.1);
  z-index: 10;
}

.feature-card-v2:hover::before {
  opacity: 1;
}

.card-icon {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(255,255,255,0.2), rgba(255,255,255,0.05));
  border-radius: 12px;
  margin-bottom: 1rem;
  transition: all 0.5s ease;
}

.feature-card-v2:hover .card-icon {
  transform: scale(1.1) rotate(5deg);
  background: linear-gradient(135deg, rgba(255,255,255,0.3), rgba(255,255,255,0.1));
}

.feature-card-v2 h3 {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 1.2rem;
  font-weight: 600;
  margin: 0 0 0.35rem 0;
  transition: all 0.3s ease;
}

.feature-card-v2:hover h3 {
  transform: translateX(5px);
}

.feature-card-v2 p {
  font-family: 'Inter', sans-serif;
  font-size: 0.85rem;
  color: rgba(255, 255, 255, 0.7);
  margin: 0;
  line-height: 1.4;
  max-height: 0;
  opacity: 0;
  overflow: hidden;
  transition: max-height 0.5s cubic-bezier(0.23, 1, 0.32, 1), opacity 0.4s ease;
}

.feature-card-v2:hover p {
  max-height: 100px;
  opacity: 1;
  margin-top: 1.0rem;
}

.feature-card-v2 p + p {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 0.75rem;
  font-style: italic;
  color: rgba(255, 255, 255, 0.45);
}

body:not(.quarto-dark) .feature-card-v2 p + p {
  color: rgba(0, 0, 0, 0.4);
}

.card-arrow {
  position: absolute;
  bottom: 1.25rem;
  right: 1.5rem;
  opacity: 0;
  transform: translateX(-10px);
  transition: all 0.3s ease;
}

.feature-card-v2:hover .card-arrow {
  opacity: 1;
  transform: translateX(0);
}

/* Light mode card styles - green tones */
body:not(.quarto-dark) .feature-card-v2 {
  background: rgba(255, 255, 255, 0.8);
  border: 1px solid rgba(0, 0, 0, 0.1);
  color: #1a2e1a;
}

body:not(.quarto-dark) .feature-card-v2:hover {
  background: rgba(255, 255, 255, 0.95);
  box-shadow:
    0 25px 50px -12px rgba(0, 0, 0, 0.2),
    0 0 40px rgba(113, 178, 128, 0.3);
}

body:not(.quarto-dark) .feature-card-v2 p {
  color: rgba(0, 0, 0, 0.6);
}

body:not(.quarto-dark) .card-icon {
  background: linear-gradient(135deg, rgba(113, 178, 128, 0.25), rgba(45, 90, 39, 0.15));
}

body:not(.quarto-dark) .card-icon svg {
  stroke: #2d5a27;
}

body:not(.quarto-dark) .card-arrow svg {
  stroke: #2d5a27;
}

/* Floating Particles */
.particles {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: -1;
  overflow: hidden;
}

.particle {
  position: absolute;
  width: 10px;
  height: 10px;
  background: rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  animation: float 20s infinite;
}

.particle:nth-child(1) { left: 10%; animation-delay: 0s; animation-duration: 25s; }
.particle:nth-child(2) { left: 30%; animation-delay: 3s; animation-duration: 20s; }
.particle:nth-child(3) { left: 50%; animation-delay: 6s; animation-duration: 30s; }
.particle:nth-child(4) { left: 70%; animation-delay: 9s; animation-duration: 22s; }
.particle:nth-child(5) { left: 90%; animation-delay: 12s; animation-duration: 28s; }

@keyframes float {
  0%, 100% {
    transform: translateY(100vh) scale(0);
    opacity: 0;
  }
  10% {
    opacity: 1;
  }
  90% {
    opacity: 1;
  }
  100% {
    transform: translateY(-100vh) scale(1);
    opacity: 0;
  }
}

/* Hide default Quarto elements on this page */
#quarto-content {
  padding: 0 !important;
}

.dynamic-page + .quarto-title-block,
#title-block-header {
  display: none;
}
